 if(empty($data['checks'])||!is_array($data['checks']))return $data;
 $active=array_map('strval',(array)get_option('active_plugins',[]));if(is_multisite())$active=array_merge($active,array_keys((array)get_site_option('active_sitewide_plugins',[])));$peepso=false;foreach($active as $plugin){if(preg_match('~^peepso-core(?:-[^/]+)?/peepso\.php$~i',$plugin)){$peepso=true;break;}}$peepso=$peepso||class_exists('PeepSo')||defined('PEEPSO_VERSION');
