 $summary=['ok'=>0,'warning'=>0,'critical'=>0,'unknown'=>0,'total'=>count($data['checks'])];foreach($data['checks'] as $check){$s=(string)($check['status']??'unknown');if(!isset($summary[$s]))$s='unknown';$summary[$s]++;}$data['summary']=$summary;$data['status']=$summary['critical']>0?'critical':($summary['warning']>0?'warning':'ok');return $data;
